let driverArchiveView=false;
import {extractDocumentText} from './document-reader.js';
const API_BASE='https://evrwtxpmhycbtvuclifb.supabase.co/functions/v1/fleet-api';
const $=s=>document.querySelector(s), content=$('#content'), drawer=$('#drawer'), small=$('#small-dialog');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const navs=[['overview','◈','Overview'],['inventory','▤','Vehicle register'],['drivers','♙','Driver Register'],['review','◇','Review queue'],['sources','▦','Source comparison'],['activity','◷','Activity & backup']];
const sourceKeys=['fleet','emc','bancorp','moventum','balance','samsara'],sourceNames={fleet:'Fleet Sheet',emc:'EMC insurance',bancorp:'Bancorp',moventum:'Moventum',balance:'Balance sheet',samsara:'Samsara'};
let data,page='overview',search='',filter='all',stateFilter='',ownershipFilter='',driverFilter='',sectionFilter='',duplicateField='',duplicateValue='',sortKey='unitNumber',sortDirection='asc',index=0,selected=null,tab='profile',importData=null,pendingSource=null,driverSearch='',driverCheckFilter='',driverSortKey='name',driverSortDirection='asc';
const checks={identity:['Vehicle identity','VIN, plate, CCS number and vehicle description physically checked.'],location:['Current location','Actual city / state confirmed, not copied from an insurance address.'],ownership:['Ownership / lease','Title or lease documentation reviewed. Accounting alone is insufficient.'],registration:['Registration','Current registration and expiry checked.'],insurance:['Insurance','Current coverage and expiry confirmed against the policy.'],condition:['Physical condition','Tires, mechanical condition and deployability inspected.'],maintenance:['Maintenance baseline','Oil change, mileage and next-service requirements reviewed.'],equipment:['Equipment, fuel & toll','Required equipment, fuel card custody and toll tag checked.']};
const fmt=d=>d?new Date(d.length===10?d+'T12:00:00':d).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'Not recorded';
const badge=(s,t='')=>`<span class="badge ${t}">${esc(s)}</span>`;
const getV=id=>data.vehicles.find(v=>v.id===id);
const label=v=>v?.unitNumber?`CCS ${v.unitNumber}`:v?.vin?`VIN …${v.vin.slice(-6)}`:'Unresolved reference';
const evidence=v=>data.evidence.filter(e=>e.vehicleId===v.id);
const issues=v=>data.issues.filter(i=>i.vehicleId===v.id&&i.status==='Open');
const sourceState=(v,s)=>{const source=data.sources.find(x=>x.id===s);const es=evidence(v).filter(e=>e.active!==false&&e.sourceId===s&&(!source?.lastAcceptedUploadId||e.uploadId===source.lastAcceptedUploadId||e.automatic&&e.uploadId===source.pendingUploadId));if(!es.length)return'Not listed';if(es.some(e=>e.needsReview))return'Identifier conflict';if(s==='samsara'&&es.some(e=>['Exact VIN','Unique plate','Confirmed Samsara equipment'].includes(e.match)&&e.fields?.serial))return'Listed';if(es.some(e=>e.reportedVin&&e.reportedVin!==v.vin))return'VIN differs';return es.some(e=>e.match==='Exact VIN'||e.match==='Confirmed accounting match'&&e.confirmedVin===v.vin)?'Listed':es.some(e=>/suffix/i.test(e.match)||e.match==='Confirmed accounting match')?'Possible match':'Supporting only';};
const reviewStatus=v=>`${issues(v).length?`<button type="button" class="badge amber" data-vehicle-reviews="${v.id}" title="Review and confirm items for this vehicle">${issues(v).length} review item${issues(v).length===1?'':'s'}</button>`:badge('No open review items','green')}<small><button type="button" class="link" data-open="${v.id}" data-tab="verify" title="Separate physical verification checklist">${v.verificationStatus==='Verified'?'Physical check complete':v.verificationStatus==='In progress'?'Physical check in progress':'Physical check pending'}</button></small>`;

function ownershipInfo(v){
 const owner=String(v.ownership||'').toLowerCase();let key='unknown',label='Not confirmed';
 if(/lease/.test(owner)){
  if(/bancorp|bankorp/.test(owner)){key='bancorp';label='Leased · Bancorp';}
  else if(/union|moventum|momentum/.test(owner)){key='moventum';label='Leased · Moventum / Union';}
  else{key='lease';label='Leased · '+(v.ownership||'Provider needed');}
 }else if(/own/.test(owner)){key='owned';label='CCS owned';}
 else if(/loan|financ|chase/.test(owner)){key='financed';label='Financed · '+v.ownership;}
 else if(!owner){
  const providers=['bancorp','moventum'].filter(s=>sourceState(v,s)==='Listed');
  if(providers.length===1){key=providers[0];label='Leased · '+(key==='bancorp'?'Bancorp':'Moventum / Union')+' (source)';}
 }
 const accounting=sourceState(v,'balance');
 return {key,label,accounting:accounting!=='Not listed',tentative:accounting!=='Listed'};
}
function ownershipCell(v){const o=ownershipInfo(v);return `${badge(o.label,o.key==='unknown'?'':'blue')}${o.accounting?`<small>${o.tentative?`<button type="button" class="badge amber" data-confirm-asset="${v.id}" title="Confirm this accounting asset match">Accounting asset · confirm match</button>`:badge('Accounting asset · confirmed','blue')}</small>`:''}${withoutAssetSource(v)?`<small>${badge('No lease / asset source','red')}</small>`:''}`;}
function driverCell(v){return v.driver?`<div class="driver-cell"><span>${esc(v.driver)}</span><button class="driver-edit" data-driver="${v.id}" aria-label="Edit driver for ${esc(label(v))}" title="Edit driver">✎</button></div>`:`<button class="compact add-driver" data-driver="${v.id}">＋ Add driver</button>`;}
function driverOptions(selectedId){return `<option value="">No driver assigned</option>${data.drivers.map(d=>`<option value="${d.id}" ${d.id===selectedId?'selected':''}>${esc(d.name)} · ${esc(d.employeeId||'')}</option>`).join('')}`;}
function assignmentData(vehicleId,driverId){const affected=data.vehicles.filter(v=>v.id===vehicleId||driverId&&v.driverId===driverId);const conflicts=affected.filter(v=>v.id===vehicleId?v.driver&&v.driverId!==driverId:v.driverId===driverId);if(conflicts.length&&!confirm('Update vehicle assignments?\n'+conflicts.map(v=>label(v)+': '+(v.driver||'Unassigned')).join('\n')+'\nExisting assignments will be cleared where needed.'))throw Error('Assignment change canceled.');return {confirmAssignment:true,assignmentVersions:Object.fromEntries(data.vehicles.map(v=>[v.id,v.version]))};}
function driverModal(id){const v=getV(id);showSmall('Change vehicle driver',`<p><b>${esc(label(v))}</b> · Current driver: ${esc(v.driver||'Not assigned')}</p><form id="driver-form" data-id="${id}" data-version="${v.version}" class="stack"><label>Driver<select name="driverId">${driverOptions(v.driverId)}</select></label><p>Choose another driver to replace the current assignment. If that driver has another vehicle, their previous assignment will be cleared after confirmation.</p><div class="error" role="alert"></div><button class="primary">Save driver assignment</button></form>`);}
function editDriverModal(id){const d=[...data.drivers,...(data.archivedDrivers||[])].find(d=>d.id===id),assigned=data.vehicles.find(v=>v.driverId===id);showSmall('Edit driver',`<form id="edit-driver-form" data-id="${d.id}" data-version="${d.version}" class="stack">${[['name','Full name'],['employeeId','Employee number'],['role','Role'],['market','Market / area'],['email','Email'],['phone','Phone']].map(([k,n])=>`<label>${n}<input name="${k}" value="${esc(d[k]||'')}" maxlength="160" ${k==='name'?'required minlength="2"':''} type="${k==='email'?'email':'text'}"></label>`).join('')}${d.archived?'<p>Restore this archived driver before assigning a vehicle.</p>':`<label>Assigned vehicle<select name="vehicleId"><option value="">No vehicle assigned</option>${data.vehicles.filter(v=>!v.mergedInto&&v.operationalState!=='Disposed').map(v=>`<option value="${v.id}" ${assigned?.id===v.id?'selected':''}>${esc(label(v))} · ${esc(v.plate)}${v.driver?' · '+esc(v.driver):''}</option>`).join('')}</select></label>`}<div class="error" role="alert"></div><button class="primary">Save driver</button></form>`);}



const duplicateLabels={unitNumber:'Vehicle number',vin:'VIN',driver:'Driver'};
function normalizedValue(v,key){let value=String(v[key]??'').trim().replace(/\s+/g,' ').toUpperCase();if(key==='vin')value=value.replace(/\s/g,'');if(key==='unitNumber'&&/^\d+$/.test(value))value=value.replace(/^0+(?=\d)/,'');return value;}
function registryVehicles(){return data.vehicles.filter(v=>page!=='inventory'||(filter==='disposed'?v.operationalState==='Disposed':v.operationalState!=='Disposed'));}
function duplicateGroups(key){const groups=new Map();for(const v of registryVehicles()){const value=normalizedValue(v,key);if(!value)continue;if(!groups.has(value))groups.set(value,{value,label:String(v[key]).trim(),count:0});groups.get(value).count++;}return [...groups.values()].filter(g=>g.count>1).sort((a,b)=>b.count-a.count||a.label.localeCompare(b.label,undefined,{numeric:true}));}
function duplicateCount(key){return duplicateGroups(key).reduce((n,g)=>n+g.count,0);}
function sortValue(v,key){
 if(key==='status'){const o=ownershipInfo(v);return (v.crashRepairActive?'Crash repair · ':'')+o.label+(o.accounting?' Accounting asset':'');}
 if(key==='sources')return String(sourceKeys.filter(s=>sourceState(v,s)==='Listed').length).padStart(3,'0')+' '+sourceKeys.map(s=>sourceState(v,s)).join(' ');
 if(key==='review')return String(issues(v).length).padStart(6,'0')+' '+v.verificationStatus;
 if(key==='unitNumber')return v.unitNumber||'';
 return v[key]||'';
}
function sortedVehicles(rows){return [...rows].sort((a,b)=>{const av=String(sortValue(a,sortKey)),bv=String(sortValue(b,sortKey));if(!av||!bv){if(!av&&bv)return 1;if(av&&!bv)return -1;}const c=av.localeCompare(bv,undefined,{numeric:true,sensitivity:'base'});return c?(sortDirection==='asc'?c:-c):String(a.id).localeCompare(String(b.id));});}
function columnHeader(key,title,sortable=true){const count=duplicateLabels[key]?duplicateCount(key):0;return `<th aria-sort="${sortable&&sortKey===key?(sortDirection==='asc'?'ascending':'descending'):'none'}"><div class="column-controls">${sortable?`<button class="sort-button" data-sort="${key}" title="Sort ${title}">${title} <span aria-hidden="true">${sortKey===key?(sortDirection==='asc'?'↑':'↓'):'↕'}</span></button>`:title}${count?`<button class="duplicate-count" data-duplicates="${key}" title="${count} records share a ${duplicateLabels[key].toLowerCase()}; click to filter" aria-label="${count} duplicate ${duplicateLabels[key].toLowerCase()} instances">${count}</button>`:''}</div>${key==='driver'?`<button class="missing-count" data-without-driver="true">${registryVehicles().filter(v=>!normalizedValue(v,'driver')).length} without driver</button>`:''}</th>`;}
function duplicatesModal(key){const groups=duplicateGroups(key),count=duplicateCount(key),max=Math.max(1,...groups.map(g=>g.count));showSmall(`${duplicateLabels[key]} duplicates`, `<p><b>${count} duplicate instances</b> across ${groups.length} repeated values.</p><p class="muted">Counts include all records in each repeated group, across the full repository. Blank values are excluded. Matching ignores capitalization and extra spaces; numeric vehicle numbers also ignore leading zeros. Selecting a bar clears other filters to show every matching record.</p>${groups.length?`<button class="compact" data-duplicate-field="${key}" data-duplicate-value="*">Show all duplicates</button><div class="histogram">${groups.map(g=>`<button class="histogram-row" data-duplicate-field="${key}" data-duplicate-value="${esc(g.value)}"><span>${esc(g.label)}</span><meter min="0" max="${max}" value="${g.count}" aria-label="${esc(g.label)}: ${g.count} records"></meter><b>${g.count}</b></button>`).join('')}</div>`:'<div class="empty">No duplicate values found.</div>'}`);}
function sectionModal(id){const v=getV(id);showSmall('CCS Section',`<p><b>${esc(label(v))}</b> · ${esc(v.plate||v.vin)}</p><form id="section-form" data-id="${id}" data-version="${v.version}" class="stack"><label>Section<select name="section"><option value="">Not recorded</option>${['Services','Valet','Sales'].map(x=>`<option ${v.section===x?'selected':''}>${x}</option>`).join('')}</select></label><small>${esc(v.sectionSource||'Not recorded')}</small><div class="error" role="alert"></div><button class="primary">Save section</button></form>`);}

const dots=v=>`<div class="source-dots">${sourceKeys.map((s,i)=>{const state=sourceState(v,s);return `<span title="${sourceNames[s]}: ${state}" class="source-dot ${state==='Listed'?'present':state!=='Not listed'?'possible':''}">${['F','I','B','M','A','S'][i]}</span>`;}).join('')}</div>`;
function vehicleExportRows(){return filtered().map(v=>{const d=(data.drivers||[]).find(d=>d.id===v.driverId),source=data.sources.find(s=>s.id==='samsara'),se=evidence(v).filter(e=>e.active!==false&&e.sourceId==='samsara'&&(!source?.lastAcceptedUploadId||e.uploadId===source.lastAcceptedUploadId||e.automatic&&e.uploadId===source.pendingUploadId));return {...v,driverName:d?.name||v.driver||'',...Object.fromEntries(Object.entries(d||{}).map(([k,val])=>['driver_'+k,val])),ownershipStatus:ownershipInfo(v).label,accountingAssetStatus:sourceState(v,'balance'),inSamsara:sourceState(v,'samsara')==='Listed'?'Yes':'Not confirmed',samsaraStatus:sourceState(v,'samsara'),samsaraDeviceIds:se.map(e=>e.fields?.deviceId||'').filter(Boolean).join('; '),samsaraSerials:se.map(e=>e.fields?.serial||'').filter(Boolean).join('; '),...Object.fromEntries(sourceKeys.map(k=>['source_'+k,sourceState(v,k)])),openReviewCount:issues(v).length,openReviewItems:issues(v).map(i=>i.message+': '+(i.details||'')).join('; '),crashRepairStatus:v.crashRepairActive?'Active crash repair':'No active crash repair',crashCount:(v.crashHistory||[]).filter(c=>c.status!=='Canceled').length,documents:data.documents.filter(d=>d.vehicleId===v.id).map(d=>d.category+': '+d.filename).join('; ')};});}
function driverExportRows(){return filteredDrivers().map(d=>({...d,assignedVehicles:data.vehicles.filter(v=>v.driverId===d.id||v.driver&&v.driver.toLowerCase()===d.name.toLowerCase()).map(v=>({vehicleNumber:v.unitNumber,vin:v.vin,plate:v.plate,operationalState:v.operationalState})),insuranceListed:driverListed(d)?'Yes':'Not confirmed',discrepancies:driverChecks(d).join('; ')}));}
function csvText(rows,baseHeaders=[]){const headers=[...new Set([...baseHeaders,...rows.flatMap(r=>Object.keys(r))])];const cell=value=>{let text=value===null||value===undefined?'':typeof value==='object'?JSON.stringify(value):String(value);if(/^[\s]*[=+@-]/.test(text)||/^[\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';};return '\uFEFF'+[headers.map(cell).join(','),...rows.map(r=>headers.map(k=>cell(r[k])).join(','))].join('\r\n');}
function downloadCsv(name,rows,headers=[]){const url=URL.createObjectURL(new Blob([csvText(rows,headers)],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Exported ${rows.length} matching rows across all pages.`);}
function exportTable(kind,context){if(kind==='vehicles')downloadCsv('CCS-vehicles-filtered',vehicleExportRows(),['unitNumber','vin','plate','section','driverName','inSamsara']);else if(kind==='drivers')downloadCsv('CCS-drivers-filtered',driverExportRows(),['name','employeeId','role']);else if(kind==='reviews'){const ids=new Set(filtered().map(v=>v.id));downloadCsv('CCS-reviews-filtered',data.issues.filter(i=>i.status==='Open'&&ids.has(i.vehicleId)).map(i=>({...i,vehicleNumber:getV(i.vehicleId)?.unitNumber,vin:getV(i.vehicleId)?.vin,plate:getV(i.vehicleId)?.plate})),['vehicleNumber','vin','plate','message']);}else if(kind.startsWith('insurance-')){const report=context==='pending'?pendingSource?.insuranceComparison:data.insuranceComparison;downloadCsv('CCS-'+kind,report?.[kind.slice(10)]||[],['name','employeeId','locator']);}else if(kind==='source-review')downloadCsv('CCS-source-comparison',pendingSource?.rows||[],['locator','kind','status','message','targetId','fields','changes']);}
function toast(m){$('#toast').textContent=m;$('#toast').className='visible';setTimeout(()=>$('#toast').className='',5500);}
async function api(path,method='GET',body){if(body?.base64&&/\.(pdf|docx)$/i.test(body.filename||'')&&path.startsWith('/api/source-upload/'))body={...body,extractedText:await extractDocumentText(body.filename,body.base64)};let r;try{r=await fetch(API_BASE+path,{method,headers:body?{'Content-Type':'application/json','X-CCS-Token':data.token}:{},body:body?JSON.stringify(body):undefined});}catch{throw Error('Connection to CCS Fleet was lost. Check your internet connection and refresh. Check Source Comparison for a pending upload before retrying.');}const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed.');return j;}

async function previewUpload(body){const job=await api('/api/source-upload/jobs','POST',body);if(job.status!=='complete')throw Error('Comparison did not complete. Check Source Comparison before retrying.');return job.result;}
function driverListed(d){if(data.insuranceComparison)return data.insuranceComparison.matchedIds.includes(d.id);const source=data.sources.find(s=>s.id==='drivers');return data.driverEvidence.some(e=>e.driverId===d.id&&e.sourceId==='drivers'&&(!source?.lastAcceptedUploadId||e.uploadId===source.lastAcceptedUploadId));}
function insuranceSummary(kind){const vehicle=kind==='vehicles',rows=vehicle?data.vehicles.filter(v=>v.operationalState!=='Disposed'):data.drivers;const missing=rows.filter(x=>vehicle?sourceState(x,'emc')!=='Listed':!driverListed(x));const groups=[...new Set(rows.map(x=>vehicle?(x.section||'Not recorded'):(x.market||'Not recorded')))];return `<section class="card"><div class="card-head"><div><h2>Insurance gaps · ${missing.length}</h2><p>Not listed in the latest insurance source; coverage needs confirmation.</p></div><button data-insurance-kind="${kind}" data-insurance-area="*">Show all ${missing.length}</button></div><div class="toolbar">${groups.sort().map(g=>`<button data-insurance-kind="${kind}" data-insurance-area="${esc(g)}">${esc(g)} · ${missing.filter(x=>(vehicle?(x.section||'Not recorded'):(x.market||'Not recorded'))===g).length}</button>`).join('')}</div></section>`;}
let driverArea='';

async function refresh(){data=await api('/api/bootstrap');data.drivers=data.drivers||[];data.driverEvidence=data.driverEvidence||[];data.uploads=data.uploads||[];render();}
function nav(p){page=p;driverArea='';driverCheckFilter='';search='';filter='all';stateFilter='';ownershipFilter='';driverFilter='';sectionFilter='';duplicateField='';duplicateValue='';index=0;location.hash=p;render();}
function render(){
 $('#add-btn').hidden=page!=='inventory';
 $('#nav').innerHTML=navs.map(([p,i,n])=>`<button data-nav="${p}" class="${p===page?'active':''}"><span class="nav-icon">${i}</span>${n}</button>`).join('');$('#title').textContent=navs.find(n=>n[0]===page)?.[2]||'Vehicle register';content.innerHTML=({overview,inventory,review,sources,drivers:driversPage,activity}[page]||overview)();
}
function stat(name,n,note,icon,action,amber=false){return `<button class="stat ${amber?'amber':''}" data-stat="${action}"><span class="stat-icon">${icon}</span><span class="stat-label">${name}</span><strong>${n}</strong><small>${note}</small></button>`;}
function overview(){const vs=data.vehicles,active=vs.filter(v=>v.operationalState!=='Disposed'),verified=active.filter(v=>v.verificationStatus==='Verified').length,open=data.issues.filter(i=>i.status==='Open');return `<section class="hero"><div><span class="hero-label">BUILD A FLEET YOU CAN TRUST</span><h2>The place for every CCS vehicle</h2><p>Collect the facts, compare the records, and verify each vehicle. Your source documents stay connected to every decision.</p></div><span class="pill">● Manual collection</span></section><div class="stats">${stat('Repository records',vs.length,`${vs.filter(v=>!v.vin).length} unresolved references · ${vs.filter(v=>v.operationalState==='Disposed').length} disposed`,'▤','all')}${stat('Verified vehicles',verified,'Physical verification required','✓','verified')}${stat('Open review items',open.length,`${active.filter(v=>issues(v).length).length} non-disposed records need review`,'◇','review',true)}${stat('Locations to collect',active.filter(v=>!v.location).length,'Current location not confirmed','⌖','location',true)}</div><div class="grid-two"><section class="card"><div class="card-head"><div><h2>Start with the gaps</h2><p>Turn source records into a reliable vehicle inventory.</p></div></div>${[['identity','Missing CCS vehicle numbers',active.filter(v=>!v.unitNumber).length,'Assign your internal vehicle number.'],['crash-repair','Active crash repairs',active.filter(v=>v.crashRepairActive).length,'Vehicles undergoing extensive crash repair.'],['location','Current location missing',active.filter(v=>!v.location).length,'Confirm where the vehicle actually is.'],['insurance','Not listed by exact VIN in EMC',active.filter(v=>sourceState(v,'emc')!=='Listed').length,'Review the supplied September 25 list and current policy.'],['review','Conflicting or incomplete records',active.filter(v=>issues(v).length).length,'Resolve differences and document the decision.']].map(([f,n,c,t])=>`<div class="list-row"><div><button class="link" data-stat="${f}">${n}</button><p>${t}</p></div>${badge(c,c?'amber':'green')}</div>`).join('')}</section><section class="card"><div class="card-head"><div><h2>Source coverage</h2><p>Full-VIN matches to the current master records.</p></div></div>${sourceKeys.map(s=>`<div class="list-row"><div><b>${sourceNames[s]}</b><p>${s==='balance'?'Partial VIN matches need review':'Loaded reference records'}</p></div><strong>${vs.filter(v=>sourceState(v,s)==='Listed').length}${s==='balance'?` <small>+ ${vs.filter(v=>sourceState(v,s)==='Possible match').length} possible</small>`:''}</strong></div>`).join('')}</section></div><div class="notice">Driver assignments are recorded manually. Repository totals include unresolved references and potential VIN conflicts; they are not a verified physical vehicle count.</div>`;}
function filtered(){return sortedVehicles(registryVehicles().filter(v=>{const hay=[...Object.values(v).filter(x=>typeof x==='string'),...evidence(v).map(e=>JSON.stringify(e.raw))].join(' ').toLowerCase().replace(/[^a-z0-9]/g,'');return (!search||hay.includes(search.toLowerCase().replace(/[^a-z0-9]/g,'')))&&(!stateFilter||v.plateState===stateFilter)&&(!ownershipFilter||(ownershipFilter==='accounting'?ownershipInfo(v).accounting:ownershipInfo(v).key===ownershipFilter))&&(!driverFilter||(driverFilter==='assigned'?!!v.driver:!v.driver))&&(!sectionFilter||(sectionFilter==='unrecorded'?!v.section:v.section===sectionFilter))&&(!duplicateField||(duplicateValue==='*'?duplicateGroups(duplicateField).some(g=>g.value===normalizedValue(v,duplicateField)):normalizedValue(v,duplicateField)===duplicateValue))&&(filter==='all'||filter==='crash-repair'&&v.crashRepairActive||filter==='verified'&&v.verificationStatus==='Verified'||filter==='review'&&issues(v).length||filter==='location'&&!v.location||filter==='identity'&&!v.unitNumber||filter==='disposed'&&v.operationalState==='Disposed'||filter==='insurance'&&sourceState(v,'emc')!=='Listed'||filter==='samsara'&&sourceState(v,'samsara')!=='Listed'||filter==='no-source'&&withoutAssetSource(v));}));}
function toolbar(){return `<div class="toolbar"><input class="search" id="search" type="search" placeholder="Search VIN, plate, CCS number, source reference…" aria-label="Search vehicles" value="${esc(search)}"><select id="filter" aria-label="Record filter">${[['all','All records'],['crash-repair','Active crash repairs'],['review','Needs review'],['verified','Verified'],['identity','Missing CCS number'],['location','Missing location'],['insurance','Not listed in EMC'],['samsara','Not listed in Samsara'],['no-source','No lease / asset source'],['disposed','Disposed']].map(([v,t])=>`<option value="${v}" ${v===filter?'selected':''}>${t}</option>`).join('')}</select><select id="state-filter" aria-label="Plate state"><option value="">All plate states</option>${[...new Set(data.vehicles.map(v=>v.plateState).filter(Boolean))].sort().map(s=>`<option ${s===stateFilter?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="ownership-filter" aria-label="Ownership status"><option value="">All ownership statuses</option>${[['bancorp','Leased · Bancorp'],['moventum','Leased · Moventum / Union'],['lease','Other lease provider'],['owned','CCS owned'],['financed','Financed'],['accounting','Accounting asset / possible match'],['unknown','Ownership not confirmed']].map(([k,n])=>`<option value="${k}" ${ownershipFilter===k?'selected':''}>${n}</option>`).join('')}</select><select id="driver-filter" aria-label="Driver assignment"><option value="">All driver assignments</option><option value="assigned" ${driverFilter==='assigned'?'selected':''}>Driver assigned</option><option value="unassigned" ${driverFilter==='unassigned'?'selected':''}>No driver assigned</option></select><select id="section-filter" aria-label="CCS section"><option value="">All CCS sections</option>${['Services','Valet','Sales'].map(x=>`<option ${sectionFilter===x?'selected':''}>${x}</option>`).join('')}<option value="unrecorded" ${sectionFilter==='unrecorded'?'selected':''}>Section not recorded</option></select>${duplicateField?`<span class="active-filter">${esc(duplicateLabels[duplicateField])}: ${esc(duplicateValue==='*'?'all duplicates':duplicateValue)} <button data-clear-duplicates="true" aria-label="Clear duplicate filter">×</button></span>`:''}</div>`;}
function pager(total){return `<div class="pagination"><span>${total?`${index*25+1}–${Math.min((index+1)*25,total)}`:'0'} of ${total} records</span><span><button data-page="-1" ${index===0?'disabled':''}>← Previous</button><button data-page="1" ${(index+1)*25>=total?'disabled':''}>Next →</button></span></div>`;}
function vehicleTable(vs,title='Vehicle register',filters=true){return `<section class="card"><div class="card-head"><div><h2>${title}</h2><p>Master values are unverified until reviewed. Open a record to compare evidence.</p></div><button data-export-table="vehicles">Export filtered CSV ↓</button></div>${filters?toolbar():''}<div class="table-wrap"><table><thead><tr>${[['unitNumber','Vehicle / CCS number'],['vin','VIN'],['plate','License plate'],['location','Current location'],['section','CCS Section'],['status','Status'],['driver','Driver'],['sources','Sources'],['review','Review status']].map(([k,n])=>columnHeader(k,n,filters)).join('')}</tr></thead><tbody>${vs.map(v=>`<tr class="${v.crashRepairActive?'crash-repair-row':''}"><td><button class="link" data-open="${v.id}">${esc(label(v))}</button><small class="vehicle-name">${esc([v.year,v.make,v.model].filter(Boolean).join(' ')||'Description needed')}</small>${v.operationalState==='Disposed'?badge('Disposed','red'):''}</td><td class="mono">${esc(v.vin||'Full VIN needed')}</td><td><b>${esc(v.plate||'Not recorded')}</b><small>${esc(v.plateState)}</small></td><td>${esc(v.location||'Not confirmed')}<small>${esc(v.region)}</small></td><td><button class="section-cell" data-section="${v.id}" title="Edit CCS section">${esc(v.section||'Not recorded')} <span aria-hidden="true">✎</span></button></td><td>${v.crashRepairActive?badge('⚠ Crash repair','crash-repair-badge'):''}${ownershipCell(v)}${v.operationalState!=='Disposed'||v.crashHistory?.length?`<button class="compact top-space" data-open="${v.id}" data-tab="crashes">${v.crashRepairActive?'View repair':v.crashHistory?.length?'Crash history':'Record crash'}</button>`:''}</td><td>${driverCell(v)}</td><td>${dots(v)}</td><td>${reviewStatus(v)}${page==='inventory'?`<button class="compact top-space" data-disposal="${v.id}">${v.operationalState==='Disposed'?'Restore vehicle':'Mark disposed'}</button>`:''}</td></tr>`).join('')}</tbody></table>${!vs.length?'<div class="empty">No records match these filters.</div>':''}</div></section>`;}
function withoutAssetSource(v){return ['bancorp','moventum','balance'].every(s=>sourceState(v,s)==='Not listed');}
function vehicleGapSummary(){const rows=data.vehicles.filter(v=>v.operationalState!=='Disposed');return `<div class="vehicle-gap-grid">${[['insurance','Insurance gaps','Not listed in the latest insurance source.',v=>sourceState(v,'emc')!=='Listed'],['samsara','Vehicles not in Samsara','No confirmed equipment match in the latest accepted CSV.',v=>sourceState(v,'samsara')!=='Listed'],['no-source','Vehicles without a source','Absent from Bancorp, Moventum and the accounting asset sheet.',withoutAssetSource]].map(([key,title,note,test])=>{const missing=rows.filter(test);return `<section class="card"><div class="card-head"><div><h3>${title} · ${missing.length}</h3><p>${note}</p></div><button data-gap="${key}" data-gap-area="*">Show all ${missing.length}</button></div><div class="toolbar">${[...new Set(rows.map(v=>v.section||'Not recorded'))].sort().map(area=>`<button data-gap="${key}" data-gap-area="${esc(area)}">${esc(area)} · ${missing.filter(v=>(v.section||'Not recorded')===area).length}</button>`).join('')}</div></section>`;}).join('')}</div>`;}
function registryTabs(){const disposed=data.vehicles.filter(v=>v.operationalState==='Disposed').length;return `<div class="actions top-space" role="group" aria-label="Vehicle storage"><button data-registry-view="current" class="${filter!=='disposed'?'primary':''}" aria-pressed="${filter!=='disposed'}">Current vehicles (${data.vehicles.length-disposed})</button><button data-registry-view="disposed" class="${filter==='disposed'?'primary':''}" aria-pressed="${filter==='disposed'}">Disposed vehicles (${disposed})</button></div>`;}
function disposalModal(id){const v=getV(id),restore=v.operationalState==='Disposed';showSmall(restore?'Restore vehicle':'Move to disposed vehicles',`<p><b>${esc(label(v))}</b> · ${esc(v.plate||v.vin)}</p><div class="notice">${restore?'Return this vehicle to the current register.':'This vehicle will leave the current register and remain in Disposed vehicles. Documents, source evidence, driver history and notes are retained.'}</div><form id="disposal-form" data-id="${v.id}" data-version="${v.version}" class="stack"><input type="hidden" name="operationalState" value="${restore?'Unknown':'Disposed'}"><label>${restore?'Restoration':'Disposal'} note<textarea name="note" required minlength="3" rows="3" placeholder="Reason and any relevant details"></textarea></label><div class="error" role="alert"></div><div class="form-footer"><button type="button" data-close="small-dialog">Cancel</button><button class="primary">${restore?'Restore to current register':'Confirm disposal'}</button></div></form>`);}
function inventory(){const vs=filtered();return `${registryTabs()}${filter==='disposed'?'<div class="notice">Disposed vehicles are stored here with their documents, source evidence and history. Open a record to inspect it, or restore it to the current register.</div>':vehicleGapSummary()}<div class="notice">Sources: F = Fleet Sheet · I = EMC insurance · B = Bancorp · M = Moventum · A = Accounting · S = Samsara. Blue means listed; amber means a tentative or supporting match. Use Add driver to record an assignment, then the pencil to edit it.</div>${vehicleTable(vs.slice(index*25,index*25+25),filter==='disposed'?'Disposed vehicles':'Current vehicles')}${pager(vs.length)}`;}
const selectedReviews=new Set();
function reviewItems(){const ids=new Set(filtered().map(v=>v.id));return data.issues.filter(i=>i.status==='Open'&&ids.has(i.vehicleId));}
function selectedReviewItems(){return reviewItems().filter(i=>selectedReviews.has(i.id));}
function review(){const items=reviewItems(),visible=new Set(items.map(i=>i.id));for(const id of selectedReviews)if(!visible.has(id))selectedReviews.delete(id);const current=items.slice(index*25,index*25+25),selected=selectedReviewItems();return `<div class="notice">Exact source matches are recorded automatically. Confirm selected closes reviewed exceptions with your note; it does not change saved vehicle fields or mark vehicles physically verified.</div><section class="card"><div class="card-head"><div><h2>Open review queue</h2><p>${items.length} items · ${selected.length} selected</p></div><div class="actions"><button data-confirm-reviews="true" ${selected.length?'':'disabled'}>Confirm selected (${selected.length})</button><button data-select-all-reviews="true" ${items.length?'':'disabled'}>Select all filtered (${items.length})</button><button data-clear-review-selection="true" ${selected.length?'':'disabled'}>Clear selection</button><button data-ignore-reviews="true" ${items.length?'':'disabled'}>Ignore all filtered discrepancies (${items.length})</button><button data-export-table="reviews">Export filtered CSV ↓</button></div></div>${toolbar()}<div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="review-page-select" aria-label="Select all review items on this page" ${current.length&&current.every(i=>selectedReviews.has(i.id))?'checked':''} ${current.length?'':'disabled'}></th><th>Vehicle</th><th>Review item</th><th>Evidence / detail</th><th></th></tr></thead><tbody>${current.map(i=>`<tr><td><input type="checkbox" data-review-select="${i.id}" aria-label="Select review item: ${esc(i.message)}" ${selectedReviews.has(i.id)?'checked':''}></td><td><button class="link" data-open="${i.vehicleId}">${esc(label(getV(i.vehicleId)))}</button><small class="mono">${esc(getV(i.vehicleId)?.vin)}</small></td><td><b>${esc(i.message)}</b><small>${esc(i.field)}</small></td><td>${esc(i.details||'Review and update the master record.')}</td><td><button class="compact" data-resolve="${i.id}">Resolve</button></td></tr>`).join('')}</tbody></table>${!items.length?'<div class="empty">No open items in this view.</div>':''}</div>${pager(items.length)}</section>`;}
let bulkReviewIds=[];
function confirmReviewsModal(){bulkReviewIds=selectedReviewItems().map(i=>i.id);if(!bulkReviewIds.length)return;showSmall('Confirm selected review items',`<p>Confirm ${bulkReviewIds.length} selected items as reviewed and resolved. Existing vehicle values stay unchanged.</p><form id="bulk-review-form" class="stack"><label>Review note for these items<textarea name="note" required minlength="10" rows="3" placeholder="What you checked and why these items are resolved"></textarea></label><div class="error" role="alert"></div><button class="primary">Confirm ${bulkReviewIds.length} selected items</button></form>`);}

function sourceFreshness(s,at=Date.now()){if(!s.lastUploadedAt)return {overdue:true,days:null,label:'No upload date recorded'};const days=Math.floor((at-Date.parse(s.lastUploadedAt))/86400000);return {overdue:days>=30,days,label:days>=30?`${days} days old · overdue`:`${Math.max(0,days)} days old · refresh monthly`};}
function sourceUploadCard(s){const c=data.sourceTypes?.[s.id],fresh=sourceFreshness(s);return `<section class="card source-card ${fresh.overdue?'source-overdue':''}"><div class="status-line">${badge(s.status,s.status==='Pending review'?'amber':s.status==='Loaded'?'blue':'')}${s.rowCount?`<small>${s.rowCount} source rows</small>`:''}</div><h3>${esc(c?.title||s.name)}</h3><p>${esc(s.note)}</p>${c?`<div class="source-upload-controls"><button class="primary compact" data-source-upload="${s.id}">${esc(c.label)}</button><span class="upload-date ${fresh.overdue?'overdue':''}"><b>Last upload:</b> ${s.lastUploadedAt?esc(fmt(s.lastUploadedAt)):'Not recorded'}<small>${fresh.label}</small></span></div><small class="source-file">${esc(s.lastFilename||s.name)}</small><small>Last approved comparison: ${s.lastAcceptedAt?esc(fmt(s.lastAcceptedAt)):'Original references / no reviewed upload yet'}</small>${s.pendingUploadId?`<button class="compact top-space" data-resume-upload="${s.pendingUploadId}">Review pending upload</button>`:''}${s.lastAcceptedUploadId&&data.uploads.some(u=>u.id===s.lastAcceptedUploadId&&u.storageAvailable)?` <a href="${API_BASE}/api/source-upload/${s.lastAcceptedUploadId}/download" download>Download latest accepted file</a>`:''}`:''}</section>`;}
function insuranceComparisonView(report,context='saved'){if(!report)return '<div class="notice">Upload the insured-driver list in Source Comparison to see insurance additions and removals.</div>';return `<details class="card insurance-collapse"><summary>Insurance driver reconciliation <span class="muted">· ${report.add.length} to add · ${report.remove.length} to review for removal · ${report.review.length} ambiguous · click to expand / collapse</span></summary><div class="dialog-body"><p>Compared with the latest accepted CC roster. These are recommendations; no insurance changes are sent.</p>${[['add','Add to insurance',report.add,'CC drivers missing from insurance'],['remove','Review for removal from insurance',report.remove,'Insurance names not in the current CC roster'],['review','Resolve ambiguous names',report.review,'Multiple CC identities match; resolve before adding or removing']].map(([key,title,rows,note])=>`<details class="insurance-sublist"><summary>${title} (${rows.length})</summary><p>${note}</p><button data-export-table="insurance-${key}" data-report-context="${context}">Export this list CSV ↓</button><div class="insurance-scroll">${rows.map(r=>`<div class="list-row">${esc(r.name)}${r.employeeId?' · '+esc(r.employeeId):''}</div>`).join('')||'<p>None</p>'}</div></details>`).join('')}</div></details>`;}

function sources(){return `<div class="notice">All imports live here. Upload each source monthly; dates turn red after 30 days. One CC CSV checks both registries. Review discrepancies before changing existing data.</div>${insuranceComparisonView(data.insuranceComparison)}<div class="source-grid">${data.sources.filter(s=>s.id!=='driverSystem').map(sourceUploadCard).join('')}</div><section class="card"><div class="card-head"><h2>Vehicle supporting documents</h2></div><form id="document-form" class="stack"><label>Vehicle<select name="vehicleId" required>${data.vehicles.map(v=>`<option value="${v.id}">${esc(label(v))} · ${esc(v.vin)}</option>`).join('')}</select></label><label>Category<select name="category"><option>Registration</option><option>Insurance</option><option>Title / lease</option><option>Condition photos</option><option>Service record</option><option>Other</option></select></label><label>File (PDF, PNG or JPEG; 5 MB)<input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg" required></label><div class="error" role="alert"></div><button class="primary">Upload supporting document</button></form></section>`;}

function activity(){return `<section class="card"><div class="card-head"><div><h2>Shared fleet data</h2><p>Supabase shared storage · changes are saved for everyone using this website.</p></div></div><div class="dialog-body"><div class="actions"><a href="${API_BASE}/api/backup" download><button class="primary">Download fleet records backup</button></a><button data-nav="inventory">Open Vehicle Registry to export filtered CSV</button></div><p class="muted">Keep downloaded backups for recovery. Table CSV exports follow the current filters and include all matching pages. Vehicle exports include linked driver and source details.</p></div></section><section class="card"><div class="card-head"><div><h2>Change history</h2><p>Latest 300 events. Full before-and-after values remain in the database.</p></div></div><div class="table-wrap"><table><thead><tr><th>When</th><th>Action</th><th>Vehicle</th><th>Note</th></tr></thead><tbody>${data.audit.map(a=>`<tr><td>${esc(new Date(a.time).toLocaleString())}</td><td>${badge(a.action)}</td><td>${a.vehicleId&&getV(a.vehicleId)?`<button class="link" data-open="${a.vehicleId}">${esc(label(getV(a.vehicleId)))}</button>`:'Workspace'}</td><td>${esc(a.note)}</td></tr>`).join('')}</tbody></table></div></section>`;}
const input=(title,key,v,type='text',attrs='')=>`<label>${title}<input name="${key}" type="${type}" value="${esc(v[key])}" ${attrs}></label>`;
const select=(title,key,v,options)=>`<label>${title}<select name="${key}">${options.map(x=>`<option ${x===v[key]?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
function openVehicle(id,t='profile'){selected=id;tab=t;const v=id?getV(id):{};drawer.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">VEHICLE RECORD</span><h2 id="dialog-title">${esc(id?label(v):'Add a CCS vehicle')}</h2><small>${esc(v.vin||'Manually collect the vehicle details')}</small></div><button class="close" data-close="drawer" aria-label="Close vehicle">×</button></div>${id?`<div class="tabs">${[['profile','Master record'],['evidence','Source evidence'],['verify','Verification'],['docs','Documents'],['crashes','Crash / repairs']].map(([k,n])=>`<button data-tab-select="${k}" class="${tab===k?'active':''}">${n}</button>`).join('')}</div>`:''}<div class="dialog-body">${({profile:profileForm,evidence:evidenceView,verify:verifyForm,docs:docsView,crashes:crashesView}[tab])(v)}</div>`;if(!drawer.open)drawer.showModal();}
function crashesView(v){const history=v.crashHistory||[];return `<div class="notice">${v.crashRepairActive?'⚠ Active crash repair — this vehicle is out of service and highlighted yellow in the registry.':'Record crashes and retain their repair history here.'}</div>${!v.crashRepairActive&&v.operationalState!=='Disposed'?`<button class="primary" data-record-crash="${v.id}">Record a crash</button>`:''}${history.slice().reverse().map(c=>`<section class="card top-space"><div class="card-head"><h3>Crash · ${esc(fmt(c.crashDate))}</h3>${badge(c.status==='Canceled'?'Canceled · entered in error':c.status==='Complete'?'Repair complete':'⚠ Crash repair',c.status==='Canceled'?'':c.status==='Complete'?'green':'crash-repair-badge')}</div><div class="dialog-body"><p>${esc(c.description)}</p><dl class="kv"><dt>Repair shop</dt><dd>${esc(c.repairShop||'Not recorded')}</dd><dt>Claim / reference</dt><dd>${esc(c.claimNumber||'Not recorded')}</dd><dt>Expected return</dt><dd>${esc(fmt(c.expectedReturn))}</dd><dt>Repair notes</dt><dd>${esc(c.repairNotes||'Not recorded')}</dd>${c.status==='Complete'?`<dt>Completed</dt><dd>${esc(fmt(c.completedDate))}</dd><dt>Completion note</dt><dd>${esc(c.completionNote)}</dd>`:''}</dl>${c.status==='Canceled'?`<p class="muted">Canceled ${esc(fmt(c.canceledAt))}: ${esc(c.cancellationNote)}</p>`:''}${!['Complete','Canceled'].includes(c.status)?`<div class="actions"><button data-edit-crash="${c.id}" data-vehicle-id="${v.id}">Update repair</button><button data-complete-crash="${c.id}" data-vehicle-id="${v.id}">Mark repair complete</button><button data-cancel-crash="${c.id}" data-vehicle-id="${v.id}">Cancel crash record</button></div>`:''}</div></section>`).join('')||'<p class="muted top-space">No crashes recorded.</p>'}`;}
const localDate=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
function cancelCrashModal(id,crashId){const v=getV(id);showSmall('Cancel incorrect crash record',`<p><b>${esc(label(v))}</b> · ${esc(v.plate||v.vin)}</p><div class="notice">Use this when the crash was entered on the wrong vehicle or recorded by mistake. The yellow flag will be removed; the canceled entry stays in history. Earlier status is restored when available; otherwise status becomes Unknown for review.</div><form id="crash-cancel-form" data-id="${v.id}" data-version="${v.version}" class="stack"><input type="hidden" name="crashId" value="${esc(crashId)}"><label>Reason<textarea name="cancellationNote" required minlength="3" maxlength="5000" rows="3">Entered on the wrong vehicle</textarea></label><div class="error" role="alert"></div><button class="primary">Cancel crash record</button></form>`);}
function crashModal(id,crashId='',complete=false){const v=getV(id),c=(v.crashHistory||[]).find(x=>x.id===crashId)||{};showSmall(complete?'Complete crash repair':crashId?'Update crash repair':'Record a crash',`<p><b>${esc(label(v))}</b> · ${esc(v.plate||v.vin)}</p><form id="crash-form" data-id="${v.id}" data-version="${v.version}" class="stack"><input type="hidden" name="action" value="${complete?'complete':crashId?'update':'record'}"><input type="hidden" name="crashId" value="${esc(crashId)}">${complete?`<div class="notice">Completion removes the yellow repair flag. Operational status becomes Unknown until you check and update it. Disposed vehicles remain disposed.</div><label>Completion date<input name="completedDate" type="date" value="${localDate()}" required></label><label>Work completed / release notes<textarea name="completionNote" minlength="3" maxlength="5000" required rows="3"></textarea></label>`:`<div class="notice">This marks the vehicle out of service and highlights its row yellow until repairs are completed.</div><label>Crash date<input name="crashDate" type="date" value="${esc(c.crashDate||localDate())}" required></label><label>Crash description<textarea name="description" minlength="3" maxlength="5000" required rows="3">${esc(c.description)}</textarea></label><label>Repair shop<input name="repairShop" maxlength="5000" value="${esc(c.repairShop)}"></label><label>Claim / reference number<input name="claimNumber" maxlength="5000" value="${esc(c.claimNumber)}"></label><label>Expected return date<input name="expectedReturn" type="date" value="${esc(c.expectedReturn)}"></label><label>Repair progress / notes<textarea name="repairNotes" maxlength="5000" rows="3">${esc(c.repairNotes)}</textarea></label>`}<div class="error" role="alert"></div><button class="primary">${complete?'Complete repair':'Save crash record'}</button></form>`);}
function profileForm(v){return `<form id="vehicle-form"><div class="status-line">${v.id?reviewStatus(v):badge('Manual entry','blue')}${badge(v.driver?'Driver: '+v.driver:'No driver assigned')}<small>Saving changes resets verification.</small></div><div class="form-grid"><div class="section-label wide">01 / IDENTITY</div>${input('CCS vehicle number','unitNumber',v)}${input('VIN (17 characters, or leave blank)','vin',v,'text','maxlength="17"')}${input('Year','year',v,'number','min="1900" max="2100"')}${input('Make','make',v)}${input('Model / provisional description','model',v)}${input('License plate','plate',v)}${input('Plate state','plateState',v,'text','maxlength="2"')}${input('Ownership / lease / financing','ownership',v)}<div class="section-label wide">02 / LOCATION & STATUS</div>${input('Confirmed current location (city, state)','location',v)}${input('Operating region','region',v)}${select('CCS Section','section',v,['','Services','Valet','Sales'])}${select('Operational status','operationalState',v,['Unknown','Available','Maintenance','Out of service','Disposed'])}${select('Inspected condition','condition',v,['Unknown','Good','Needs attention','Unsafe'])}<div class="section-label wide">03 / REGISTRATION & INSURANCE</div>${input('Registration expiry','registrationExpiry',v,'date')}${input('Confirmed insurance expiry','insuranceExpiry',v,'date')}<div class="section-label wide">04 / MAINTENANCE, FUEL & EQUIPMENT</div>${input('Odometer (miles)','odometer',v,'number','min="0"')}${input('Odometer recorded on','odometerDate',v,'date')}${input('Last oil change date','lastOilChange',v,'date')}${input('Last oil change mileage','lastOilMileage',v,'number','min="0"')}${input('Next service date','pmDueDate',v,'date')}${input('Next service mileage','pmDueMiles',v,'number','min="0"')}${input('Tire condition','tireCondition',v)}${input('Mechanical observations','mechanicalNotes',v)}${input('Fuel card provider','fuelProvider',v)}${input('Fuel card last four digits','fuelCard',v,'text','maxlength="4"')}${input('Toll transponder number','tollTag',v)}<label>Driver assignment<select name="assignmentDriverId">${v.driver&&!v.driverId?`<option value="__keep__" selected>${esc(v.driver)} (existing assignment)</option>`:''}${driverOptions(v.driverId)}</select><small>Choose a driver to assign or replace.</small></label><label class="wide">Notes<textarea name="notes" rows="3">${esc(v.notes)}</textarea></label></div><div class="error" role="alert"></div><div class="form-footer">${v.id?`<button type="button" data-merge="${v.id}" class="danger">Reconcile duplicate</button>`:''}<button type="button" data-close="drawer">Cancel</button><button class="primary">Save vehicle</button></div></form>`;}
function evidenceView(v){const es=evidence(v),is=data.issues.filter(i=>i.vehicleId===v.id);return `<div class="notice">Initial master values favor the Fleet Sheet, then lease records, then EMC. Source values are preserved below. Current location and driver were not inferred.</div><h3>Review items</h3>${is.length?is.map(i=>`<div class="evidence-card"><div class="list-row"><div><b>${esc(i.message)}</b><p>${esc(i.details)}</p>${i.resolution?`<small>${esc(i.resolution)}</small>`:''}</div>${i.status==='Open'?`<button class="compact" data-resolve="${i.id}">Resolve</button>`:badge('Resolved','green')}</div></div>`).join(''):'<p class="muted">No outstanding source conflicts recorded.</p>'}<div class="card-head"><h3>Source evidence (${es.length})</h3><button class="compact" data-add-evidence="${v.id}">＋ Add evidence</button></div>${es.map(e=>`<div class="evidence-card"><h3>${esc(data.sources.find(s=>s.id===e.sourceId)?.name||e.sourceId)}</h3><div class="status-line">${badge(e.match,/suffix/i.test(e.match)?'amber':'blue')}<small>${esc(e.locator)}</small>${e.image?`<a target="_blank" rel="noopener" href="${esc(e.image)}">View source image ↗</a>`:''}</div><details><summary>View original source values</summary><dl class="kv">${Object.entries(e.raw).map(([k,x])=>`<dt>${esc(k)}</dt><dd>${esc(typeof x==='object'?JSON.stringify(x):x)}</dd>`).join('')}</dl></details></div>`).join('')}`;}
function verifyForm(v){return `<form id="verify-form"><div class="notice amber">Only check items you have personally reviewed. Complete verification requires all eight checks, supporting master details, and no open review items. Driver assignments are excluded.</div><div class="status-line">${reviewStatus(v)}${v.verifiedBy?`<small>Last reviewer: ${esc(v.verifiedBy)} ${v.verifiedAt?'· '+fmt(v.verifiedAt):''}</small>`:''}</div>${Object.entries(checks).map(([k,[title,desc]])=>`<label class="check"><input type="checkbox" name="${k}" ${v.checks?.[k]?'checked':''}><span><strong>${title}</strong><small>${desc}</small></span></label>`).join('')}<div class="stack top-space"><label>Reviewer name<input name="reviewer" required minlength="2" value="${esc(v.verifiedBy)}"></label><label>Evidence / verification note<textarea name="note" required minlength="10" rows="3">${esc(v.verificationNote)}</textarea></label></div><div class="error" role="alert"></div><div class="form-footer"><button class="primary">Save verification progress</button></div></form>`;}
function docsView(v){const docs=data.documents.filter(d=>d.vehicleId===v.id);return `<div class="notice">Attach registrations, insurance cards, condition photos or service records. PDF, PNG and JPEG up to 5 MB per file. Files are stored inside the local database.</div><div class="file-list">${docs.map(d=>`<div class="list-row"><div><b>${esc(d.filename)}</b><p>${esc(d.category)} · ${fmt(d.createdAt)} · ${Math.round(d.bytes/1024)} KB</p></div><a href="${API_BASE}/api/documents/${d.id}" download>Download ↓</a></div>`).join('')||'<div class="empty">No vehicle documents attached yet.</div>'}</div><p class="muted">Add supporting documents in Source Comparison.</p>`;}
function showSmall(title,body){small.classList.remove('wide-dialog');small.innerHTML=`<div class="dialog-head"><h2 id="small-title">${title}</h2><button class="close" data-close="small-dialog" aria-label="Close dialog">×</button></div><div class="dialog-body">${body}</div>`;if(!small.open)small.showModal();}
function importModal(sourceId='cc'){sourceUploadModal(sourceId);}
function sourceUploadModal(sourceId){const c=data.sourceTypes?.[sourceId];if(!c){toast('Refresh the app after updating the server.');return;}showSmall('Upload source for comparison',`<div class="notice">Choose the original report. Existing trucks and drivers are checked before any master changes. You will review discrepancies and approve changes on the next screen.</div><form id="source-upload-form" class="stack"><label>Source<select name="sourceId" id="upload-source">${Object.entries(data.sourceTypes).filter(([id])=>id!=='driverSystem').map(([id,x])=>`<option value="${id}" ${id===sourceId?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label id="upload-file-label">${esc(c.label)}<input name="file" type="file" accept="${c.accept}" required></label><small><a href="./driver-register-template.csv" download>Driver Register CSV template ↓</a></small><small id="upload-format-help">Maximum 30 MB. Word images and scanned PDFs may take longer to read. OCR VINs must be checked against the document.</small><div class="error" role="alert"></div><div id="upload-progress" role="status"></div><button class="primary">Upload and check existing records</button></form>`);}
async function fileBase64(file){if(file.size>30*1024*1024)throw Error('Source files must be under 30 MB.');return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('Could not read this file.'));r.readAsDataURL(file);});}
async function resumeUpload(id){const prior=await api('/api/source-upload/'+id);pendingSource=prior.status==='Accepted'?prior:await previewUpload({uploadId:id,overrides:prior.overrides||{}});await refresh();sourceReviewModal();}
function sourceReviewModal(){const u=pendingSource;if(u.status==='Accepted'){showSmall('Matches saved automatically',`<div class="notice">${esc(u.filename)}: ${u.automaticCount||u.rows.filter(r=>r.automatic).length} exact matches saved. No confirmation needed.</div><button data-close="small-dialog">Done</button>`);return;}const count=status=>u.rows.filter(r=>r.status===status).length;showSmall('Review source discrepancies',`<div class="notice"><b>${esc(u.filename)}</b><br><span id="decision-summary">${count('changes')} needed changes · ${count('ignored')} ignored</span> · ${count('new')} new candidates · ${u.rows.filter(r=>r.automatic).length} matches saved automatically · ${count('blocked')} blocked rows. Existing values stay unchanged unless you select Apply changes. New records require Add record.</div>${u.insuranceComparison?insuranceComparisonView(u.insuranceComparison,'pending'):''}${u.warnings.map(w=>`<p class="warning-text">${esc(w)}</p>`).join('')}${u.missingVehicleIds?.length?`<p class="warning-text">${u.missingVehicleIds.length} previously listed vehicles are missing from this report. Bancorp, Moventum and asset-list coverage is checked together; absence from one is allowed when another lists the vehicle. None will be deleted.</p>`:''}${u.missingDriverIds?.length?`<p class="warning-text">${u.missingDriverIds.length} registered drivers are not matched in this export. After approval they leave the active CC register; history is retained.</p>`:''}<div class="actions top-space">${u.sourceId==='cc'?'<button data-select-driver-adds="true">Select new drivers</button><button data-select-assignments="true">Select unambiguous assignments</button>':''}<button data-change-all="true">Change all eligible discrepancies</button><button data-ignore-all="true">Ignore all discrepancies</button><button data-keep-source-values="true">Reset decisions</button><button data-export-table="source-review">Export comparison CSV ↓</button></div><form id="source-review-form"><div class="review-table-wrap"><table class="upload-review-table"><thead><tr><th>Record / source row</th><th>Match and discrepancies</th><th>Your decision</th></tr></thead><tbody>${u.rows.filter(r=>!r.automatic).map(r=>{const isDriver=['driver','insuredDriver'].includes(r.kind),v=r.targetId?(isDriver?data.drivers.find(d=>d.id===r.targetId):getV(r.targetId)):null;const options=isDriver?data.drivers:data.vehicles;const needsMatch=r.status==='blocked'||r.status==='unmatched'||r.manuallyMatched;return `<tr><td><b>${esc(r.kind==='assignment'?r.driverName:r.fields.name||r.fields.vin||r.raw.description||r.fields.vinSuffix||'Source row')}</b><small>${esc(r.kind)} · ${esc(r.locator)}</small>${r.fields.role?`<small>Role: ${esc(r.fields.role)}</small>`:''}${r.kind==='vehicle'&&r.status==='blocked'?`<label class="review-correction">Correct VIN<input data-correct-vin="${r.key}" value="${esc(r.fields.vin)}" maxlength="17"></label>`:''}</td><td>${badge(r.status,r.status==='blocked'?'red':r.status==='changes'||r.status==='new'?'amber':'blue')}<p>${esc(r.message)}</p>${v?`<small>Matched: ${esc(isDriver?v.name:label(v))}</small>`:''}${r.changes.length?`<dl class="diff-list">${r.changes.map(d=>`<dt>${esc(d.field)}</dt><dd><span class="diff-old">${esc(d.before||'(blank)')}</span> → <strong>${esc(d.after)}</strong></dd>`).join('')}</dl>`:''}${r.checks?`<dl class="diff-list">${r.checks.map(d=>`<dt>${esc(d.field)}</dt><dd>Saved: ${esc(d.existing||'(blank)')} · CC: ${esc(d.reported||'(blank)')}</dd>`).join('')}</dl>`:''}${needsMatch?`<label class="review-correction">Match an existing ${isDriver?'driver':'truck'}<select data-match-row="${r.key}"><option value="">Keep unresolved</option>${options.map(x=>`<option value="${x.id}" ${u.overrides?.[r.key]?.targetId===x.id?'selected':''}>${esc(isDriver?x.name+' · '+(x.employeeId||''):label(x)+' · '+x.vin+' · '+x.plate)}</option>`).join('')}</select></label>`:''}</td><td><select name="${r.key}" ${r.status==='blocked'?'disabled':''}><option value="keep">Keep pending / no add</option>${r.targetId&&r.changes.length&&r.status!=='blocked'?`<option value="ignore" ${r.status==='ignored'?'selected':''}>Ignore discrepancy</option>`:''}${r.status==='new'?'<option value="add">Add record</option>':''}${r.targetId&&r.changes.length&&r.status!=='blocked'?'<option value="apply">Apply listed changes</option>':''}</select>${r.kind==='assignment'?'<small>Clear matches link automatically after driver data is saved. Conflicting assignments require explicit review.</small>':''}</td></tr>`;}).join('')}</tbody></table></div><div class="notice top-space">Exact matches are already saved. Confirmation applies only to the remaining exceptions and roster/source removals. Change all selects existing matched rows only; it never adds records or resolves blocked/conflicting assignments. Ignore keeps saved values and removes those discrepancies from needed changes after confirmation. Previously ignored identical differences stay ignored; changed source values are reviewed again. Saved driver VIN / plate matches automatically link the registries; conflicting assignments stay unchanged. Applying a source change resets the vehicle’s verification. A source listing does not establish driver clearance.</div><label class="check"><input type="checkbox" name="confirmed" required><span>I reviewed these discrepancies and approve only the selected changes.</span></label><div class="error" role="alert"></div><div class="form-footer"><button type="button" data-recheck-upload="true">Recheck matches / corrections</button><button id="approve-upload" class="primary">Confirm reviewed exceptions</button></div></form>`);small.classList.add('wide-dialog');}
function driverChecks(d){const messages=(data.driverLinkChecks||[]).filter(x=>x.driverId===d.id&&(x.reason||x.warning)).map(x=>x.reason||x.warning),byVIN=data.vehicles.filter(v=>d.reportedVin&&v.vin===d.reportedVin),byPlate=data.vehicles.filter(v=>d.reportedPlate&&String(v.plate).replace(/[^A-Za-z0-9]/g,'').toUpperCase()===String(d.reportedPlate).replace(/[^A-Za-z0-9]/g,'').toUpperCase());if(d.reportedVin&&!byVIN.length)messages.push('VIN not in vehicle register');if(d.reportedPlate&&!byPlate.length)messages.push('Plate not in vehicle register');if(byVIN.length===1&&d.reportedPlate&&String(byVIN[0].plate).replace(/[^A-Za-z0-9]/g,'').toUpperCase()!==String(d.reportedPlate).replace(/[^A-Za-z0-9]/g,'').toUpperCase())messages.push('VIN / plate discrepancy');const source=data.sources.find(s=>s.id==='cc');if(source?.lastAcceptedUploadId&&!data.driverEvidence.some(e=>e.driverId===d.id&&e.sourceId==='cc'&&e.uploadId===source.lastAcceptedUploadId))messages.push('Not in latest CC export');return messages;}
function driverHasVehicle(d){return data.vehicles.some(v=>!v.mergedInto&&v.operationalState!=='Disposed'&&(v.driverId===d.id||!v.driverId&&v.driver&&v.driver.trim().toLowerCase()===d.name.trim().toLowerCase()));}
function driverMetricRows(kind){return (data.drivers||[]).filter(d=>kind==='unassigned'?!driverHasVehicle(d):!driverListed(d));}
function driverMetrics(){return `<div class="driver-metrics">${[['unassigned','Drivers without a vehicle','No current vehicle assigned'],['insurance','Drivers not on insurance','Not listed in the latest insurance source; coverage needs confirmation']].map(([kind,title,note])=>{const rows=driverMetricRows(kind),selected=driverCheckFilter===kind&&!driverArchiveView;const groups=[...new Set(rows.map(d=>d.market||'Not recorded'))].map(area=>({area,count:rows.filter(d=>(d.market||'Not recorded')===area).length})).sort((a,b)=>b.count-a.count||a.area.localeCompare(b.area));const max=Math.max(1,...groups.map(g=>g.count));return `<section class="driver-metric ${selected?'selected':''}"><button class="driver-metric-main" data-driver-metric="${kind}" aria-pressed="${selected}" aria-expanded="${selected}"><span>${title}</span><strong>${rows.length}</strong><small>${note}</small><small>${selected?'Click to show all drivers':'Click to filter drivers and show area breakdown'}</small></button>${selected?`<div class="driver-histogram"><div class="actions"><button data-driver-metric-area="*">All areas · ${rows.length}</button>${driverArea?`<span>Area: ${esc(driverArea)}</span>`:''}</div>${groups.map(g=>`<button class="driver-histogram-bar ${driverArea===g.area?'active':''}" data-driver-metric-area="${esc(g.area)}" aria-pressed="${driverArea===g.area}" style="--bar-width:${100*g.count/max}%"><span>${esc(g.area)}</span><b>${g.count}</b></button>`).join('')||'<p class="muted">No drivers in this group.</p>'}</div>`:''}</section>`;}).join('')}</div>`;}
function filteredDrivers(){let rows=(driverArchiveView?data.archivedDrivers||[]:data.drivers||[]).filter(d=>(!driverArea||(d.market||'Not recorded')===driverArea)&&(!driverSearch||Object.values(d).join(' ').toLowerCase().includes(driverSearch.toLowerCase()))&&(!driverCheckFilter||(driverCheckFilter==='insurance'?!driverListed(d):driverCheckFilter==='issues'?driverChecks(d).length:!driverHasVehicle(d))));rows.sort((a,b)=>String(a[driverSortKey]||'').localeCompare(String(b[driverSortKey]||''),undefined,{numeric:true,sensitivity:'base'})*(driverSortDirection==='asc'?1:-1));return rows;}
function driversPage(){const rows=filteredDrivers();return `<div class="notice">Add drivers here or maintain their details through CC uploads. Manual entries remain active until matched to CC. Archive employees who have left to retain their history.</div><section class="card"><div class="card-head"><div><h2>${driverArchiveView?'Archived drivers':'Driver Register'} (${driverArchiveView?(data.archivedDrivers||[]).length:data.drivers.length})</h2><p>${rows.length} matching drivers · Unique people, source checks, reported vehicles and confirmed assignments.</p></div><button data-export-table="drivers">Export filtered CSV ↓</button></div>${driverArchiveView?'':driverMetrics()}<div class="actions"><button data-driver-view="active">Active drivers (${data.drivers.length})</button><button data-driver-view="archived">Archived drivers (${(data.archivedDrivers||[]).length})</button><button class="primary" data-new-driver="true">＋ Add a driver</button></div><div class="toolbar"><input id="driver-search" class="search" type="search" value="${esc(driverSearch)}" placeholder="Search name, employee number, role, VIN or plate" aria-label="Search drivers"><select id="driver-check-filter"><option value="">All drivers</option><option value="insurance" ${driverCheckFilter==='insurance'?'selected':''}>Insurance listing not confirmed</option><option value="issues" ${driverCheckFilter==='issues'?'selected':''}>Source discrepancies</option><option value="unassigned" ${driverCheckFilter==='unassigned'?'selected':''}>No confirmed vehicle assignment</option></select></div><div class="table-wrap"><table><thead><tr>${[['name','Name'],['employeeId','Employee #'],['role','CC role'],['reportedVin','CC VIN'],['reportedPlate','CC plate'],['canDrive','CC Can Drive']].map(([k,n])=>`<th><button class="sort-button" data-driver-sort="${k}">${n} ${driverSortKey===k?(driverSortDirection==='asc'?'↑':'↓'):'↕'}</button></th>`).join('')}<th>Assigned CCS vehicle</th><th>Checks / insurance listing</th><th></th></tr></thead><tbody>${rows.map(d=>{const assigned=data.vehicles.filter(v=>v.driverId===d.id||v.driver&&v.driver.toLowerCase()===d.name.toLowerCase()),check=driverChecks(d),insurance=data.sources.find(s=>s.id==='drivers'),listed=driverListed(d);return `<tr><td><button class="link" data-edit-driver="${d.id}">${esc(d.name)}</button><small>${esc(d.email||'')}</small>${d.manualAdded?'<small>Manual entry · pending CC match</small>':''}${d.aliases?.length?`<small>Also known as: ${esc(d.aliases.join('; '))}</small>`:''}</td><td>${esc(d.employeeId)}</td><td>${esc(d.role)}${d.systemRole?`<small>System role: ${esc(d.systemRole)}</small>`:''}<small>${esc(d.market||'')}</small></td><td class="mono">${esc(d.reportedVin||'Not reported')}</td><td>${esc(d.reportedPlate||'Not reported')}</td><td>${esc(d.canDrive||'Not reported')}<small>Drives CCS: ${esc(d.drivesCCS||'Not reported')}</small></td><td>${assigned.map(v=>`<button class="link" data-open="${v.id}">${esc(label(v))}</button>`).join('<br>')||'Not assigned'}</td><td>${check.map(x=>badge(x,'amber')).join(' ')||badge('No identifier discrepancy','blue')}<small>${listed?'Listed in supplied driver insurance source':'Insurance listing not confirmed'}</small></td><td><button class="compact" data-driver-details="${d.id}">View source details</button>${d.archived?`<small>Archived ${esc(fmt(d.archivedAt))}: ${esc(d.archiveNote)}</small>`:`<button class="compact" data-driver-aliases="${d.id}">Aliases${d.aliases?.length?' ('+d.aliases.length+')':''}</button>`}<button class="compact" data-driver-archive="${d.id}">${d.archived?'Restore driver':'Archive driver'}</button></td></tr>`;}).join('')}</tbody></table>${!rows.length?'<div class="empty">No drivers match. Manage imports in Source Comparison.</div>':''}</div></section>`;}
function driverDetails(id){const d=[...data.drivers,...(data.archivedDrivers||[])].find(x=>x.id===id);showSmall('Driver source details',`<h3>${esc(d.name)}</h3><dl class="kv">${Object.entries(d).filter(([k])=>!['id','version'].includes(k)).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><h3 class="top-space">Source history</h3>${data.driverEvidence.filter(e=>e.driverId===id).map(e=>`<div class="evidence-card"><b>${esc(data.sources.find(s=>s.id===e.sourceId)?.name)}</b><small>${esc(e.locator)}</small><dl class="kv">${Object.entries(e.fields).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl></div>`).join('')}`);}

function resolveModal(id){const i=data.issues.find(i=>i.id===id);showSmall('Resolve review item',`<p><b>${esc(i.message)}</b></p><p class="muted">${esc(i.details)}</p><div class="notice">Correct the master record as needed, then record your decision here. Source evidence is retained.</div><form id="resolve-form" data-id="${id}" class="stack"><label>Resolution and evidence<textarea name="note" required minlength="10" rows="4"></textarea></label><div class="error" role="alert"></div><button class="primary">Mark resolved</button></form>`);}
function mergeModal(id){const v=getV(id);showSmall('Reconcile duplicate records',`<div class="notice amber">The selected destination keeps its master values. All source evidence, review items and documents move to it. This record is archived, and the full merge is recorded in history. Confirm the VIN against physical evidence first.</div><p>Record to archive: <b>${esc(label(v))}</b> · <span class="mono">${esc(v.vin)}</span></p><form id="merge-form" data-id="${id}" class="stack"><label>Keep this destination record<select name="targetId" required><option value="">Choose the confirmed master…</option>${data.vehicles.filter(x=>x.id!==id).map(x=>`<option value="${x.id}">${esc(label(x))} — ${esc(x.vin||x.model)}</option>`).join('')}</select></label><label>Why are these the same vehicle?<textarea name="note" required minlength="10"></textarea></label><div class="error" role="alert"></div><button class="primary">Merge evidence and archive duplicate</button></form>`);}
function confirmAssetModal(id){const v=getV(id),source=data.sources.find(s=>s.id==='balance'),refs=evidence(v).filter(e=>e.active!==false&&e.sourceId==='balance'&&(!source?.lastAcceptedUploadId||e.uploadId===source.lastAcceptedUploadId||e.automatic&&e.uploadId===source.pendingUploadId));showSmall('Confirm accounting asset match',`<p><b>${esc(label(v))}</b> · ${esc(v.vin)}</p><div class="notice">Being on the asset list and Bancorp or Moventum is valid. This yellow label means the accounting entry used a partial VIN. Confirm that the entries below belong to this vehicle.</div>${refs.map(e=>`<section class="evidence-card"><b>${esc(e.locator)}</b><p>${esc(e.raw?.description||e.fields?.description||'Accounting reference')}</p><p>VIN reference: ${esc(e.raw?.vinSuffix||e.fields?.vinSuffix||e.reportedVin||'Not recorded')}</p></section>`).join('')}<form id="confirm-asset-form" data-id="${v.id}" data-version="${v.version}"><div class="error" role="alert"></div><button class="primary">Confirm this asset match</button></form><p class="muted">This confirms the source link only. It does not complete the physical vehicle checklist.</p>`);}
function vehicleReviewsModal(id){const v=getV(id),items=issues(v);bulkReviewIds=items.map(i=>i.id);showSmall('Review vehicle items',`<p><b>${esc(label(v))}</b> · ${esc(v.vin)}</p>${items.map(i=>`<section class="evidence-card"><b>${esc(i.message)}</b><p>${esc(i.details)}</p></section>`).join('')}${items.length?`<form id="bulk-review-form" class="stack"><label>Review note<textarea name="note" required minlength="10" rows="3"></textarea></label><div class="error" role="alert"></div><button class="primary">Confirm ${items.length} reviewed item${items.length===1?'':'s'}</button></form>`:'<p>No open review items.</p>'}`);}
function archiveDriverModal(id){const d=[...data.drivers,...(data.archivedDrivers||[])].find(x=>x.id===id);showSmall(d.archived?'Restore driver':'Archive departed driver',`<p><b>${esc(d.name)}</b> · ${esc(d.employeeId)}</p><div class="notice">${d.archived?'Restore to the active register if this driver is in the latest CC roster. Vehicle assignments must be reviewed again.':'Archiving clears vehicle assignments and removes the driver from active counts. Source history is retained. If still insured, this person appears for insurance removal review.'}</div><form id="driver-archive-form" data-id="${d.id}" data-version="${d.version}" data-archived="${!d.archived}" class="stack"><label>Reason<textarea name="note" minlength="3" maxlength="5000" required>${d.archived?'Returned to company':'Left the company'}</textarea></label><div class="error" role="alert"></div><button class="primary">${d.archived?'Restore driver':'Archive driver'}</button></form>`);}
function aliasModal(id){const d=data.drivers.find(d=>d.id===id);showSmall('Insurance name aliases',`<p><b>${esc(d.name)}</b> · CC remains the source of truth for this driver.</p><p>Add alternate full names used on insurance records, one per line. For Matt Gladden, enter Robert Gladden. This matches the same person without renaming or creating a driver.</p><form id="alias-form" data-id="${d.id}" data-version="${d.version}" class="stack"><label>Alternate names<textarea name="aliases" rows="5">${esc((d.aliases||[]).join('\n'))}</textarea></label><small>Remove a line to remove that alias. Saving immediately rechecks the accepted insurance list.</small><div class="error" role="alert"></div><button class="primary">Save aliases and recheck insurance</button></form>`);}
function updateDecisionSummary(){if(!pendingSource)return;let needed=0,ignored=0,apply=0;for(const row of pendingSource.rows.filter(r=>r.changes.length&&r.targetId&&r.status!=='blocked')){const select=small.querySelector(`[name="${row.key}"]`);if(select?.value==='ignore')ignored++;else if(select?.value==='apply')apply++;else needed++;}const summary=$('#decision-summary');if(summary)summary.textContent=`${needed} needed changes · ${apply} selected to change · ${ignored} ignored`;}
function setAllDiscrepancies(action){for(const row of pendingSource.rows.filter(r=>r.targetId&&r.changes.length&&r.status!=='blocked')){if(action==='apply'&&row.assignmentConflict)continue;const select=small.querySelector(`[name="${row.key}"]`);if(select){select.value=action;select.dispatchEvent(new Event('change',{bubbles:true}));}}updateDecisionSummary();}
document.addEventListener('click',async event=>{const el=event.target.closest('button,[data-open]');if(!el)return;try{
 if(el.dataset.confirmAsset)confirmAssetModal(el.dataset.confirmAsset);
 if(el.dataset.vehicleReviews)vehicleReviewsModal(el.dataset.vehicleReviews);
 if(el.dataset.recordCrash)crashModal(el.dataset.recordCrash);
 if(el.dataset.editCrash)crashModal(el.dataset.vehicleId,el.dataset.editCrash);
 if(el.dataset.driverMetric){const same=driverCheckFilter===el.dataset.driverMetric&&!driverArchiveView;driverArchiveView=false;driverCheckFilter=same?'':el.dataset.driverMetric;driverArea='';driverSearch='';render();}
 if(el.dataset.driverMetricArea){driverArea=el.dataset.driverMetricArea==='*'?'':el.dataset.driverMetricArea;render();}
 if(el.dataset.driverView){driverArchiveView=el.dataset.driverView==='archived';driverArea='';driverCheckFilter='';render();}
 if(el.dataset.driverArchive)archiveDriverModal(el.dataset.driverArchive);
 if(el.dataset.cancelCrash)cancelCrashModal(el.dataset.vehicleId,el.dataset.cancelCrash);
 if(el.dataset.completeCrash)crashModal(el.dataset.vehicleId,el.dataset.completeCrash,true);
 if(el.dataset.confirmReviews)confirmReviewsModal();
 if(el.dataset.selectAllReviews){for(const item of reviewItems())selectedReviews.add(item.id);render();}
 if(el.dataset.clearReviewSelection){selectedReviews.clear();render();}
 if(el.dataset.driverAliases)aliasModal(el.dataset.driverAliases);
 if(el.dataset.changeAll)setAllDiscrepancies('apply');
 if(el.dataset.ignoreAll)setAllDiscrepancies('ignore');
 if(el.dataset.ignoreReviews){const ids=new Set(filtered().map(v=>v.id)),items=data.issues.filter(i=>i.status==='Open'&&ids.has(i.vehicleId));if(items.length&&confirm(`Ignore ${items.length} filtered review items? Saved values stay unchanged; these items leave the needed-change count.`)){await api('/api/issues/ignore','POST',{ids:items.map(i=>i.id)});await refresh();toast(`${items.length} discrepancies ignored.`);}}
 if(el.dataset.gap){nav('inventory');filter=el.dataset.gap;sectionFilter=el.dataset.gapArea==='*'?'':el.dataset.gapArea==='Not recorded'?'unrecorded':el.dataset.gapArea;render();}
 if(el.dataset.registryView){nav('inventory');filter=el.dataset.registryView==='disposed'?'disposed':'all';render();}
 if(el.dataset.disposal)disposalModal(el.dataset.disposal);
 if(el.dataset.exportTable)exportTable(el.dataset.exportTable,el.dataset.reportContext);
 if(el.dataset.nav)nav(el.dataset.nav);
 if(el.dataset.stat){const f=el.dataset.stat;nav(f==='review'?'review':'inventory');filter=f==='review'?'all':f;render();}
 if(el.dataset.open)openVehicle(el.dataset.open,el.dataset.tab||'profile');
 if(el.dataset.close)$('#'+el.dataset.close).close();
 if(el.dataset.tabSelect)openVehicle(selected,el.dataset.tabSelect);
 if(el.dataset.page){index+=Number(el.dataset.page);render();}
 if(el.dataset.insuranceKind){if(el.dataset.insuranceKind==='vehicles'){nav('inventory');filter='insurance';sectionFilter=el.dataset.insuranceArea==='*'?'':el.dataset.insuranceArea==='Not recorded'?'unrecorded':el.dataset.insuranceArea;}else{nav('drivers');driverCheckFilter='insurance';driverArea=el.dataset.insuranceArea==='*'?'':el.dataset.insuranceArea;driverSearch='';}render();}
 if(el.dataset.sourceUpload)sourceUploadModal(el.dataset.sourceUpload);
 if(el.dataset.resumeUpload)await resumeUpload(el.dataset.resumeUpload);
 if(el.dataset.reviewInitialCc){el.disabled=true;try{pendingSource=await previewUpload({initial:true});await refresh();sourceReviewModal();}finally{el.disabled=false;}}
 if(el.dataset.driverDetails)driverDetails(el.dataset.driverDetails);
 if(el.dataset.driverSort){if(driverSortKey===el.dataset.driverSort)driverSortDirection=driverSortDirection==='asc'?'desc':'asc';else{driverSortKey=el.dataset.driverSort;driverSortDirection='asc';}render();}
 if(el.dataset.editDriver)editDriverModal(el.dataset.editDriver);
 if(el.dataset.newDriver)showSmall('Add driver to register',`<form id="new-driver-form" class="stack"><label>Full name<input name="name" required minlength="2" maxlength="160"></label><label>Employee number<input name="employeeId" maxlength="160"></label><label>Role<input name="role" maxlength="160"></label><label>Market / area<input name="market" maxlength="160"></label><label>Email<input name="email" type="email" maxlength="160"></label><label>Phone<input name="phone" type="tel" maxlength="160"></label><label>Assign a vehicle (optional)<select name="vehicleId"><option value="">No vehicle assignment</option>${data.vehicles.filter(v=>!v.mergedInto&&v.operationalState!=='Disposed'&&!v.driver&&!v.driverId).map(v=>`<option value="${v.id}">${esc(label(v))} · ${esc(v.plate||v.vin)}</option>`).join('')}</select></label><small>The driver will be checked against insurance and future CC uploads. Existing driver records cannot be duplicated.</small><div class="error" role="alert"></div><button class="primary">Add driver</button></form>`);
 if(el.dataset.selectDriverAdds)for(const row of pendingSource.rows.filter(r=>r.kind==='driver'&&r.status==='new'))small.querySelector(`[name="${row.key}"]`).value='add';
 if(el.dataset.selectAssignments)for(const row of pendingSource.rows.filter(r=>r.kind==='assignment'&&r.status==='changes'&&!r.assignmentConflict&&r.checks?.every(c=>String(c.existing||'').replace(/[^a-z0-9]/gi,'').toUpperCase()===String(c.reported||'').replace(/[^a-z0-9]/gi,'').toUpperCase())))small.querySelector(`[name="${row.key}"]`).value='apply';
 if(el.dataset.keepSourceValues){for(const select of small.querySelectorAll('#source-review-form select[name]')){select.value='keep';select.dispatchEvent(new Event('change',{bubbles:true}));}updateDecisionSummary();}
 if(el.dataset.recheckUpload){const overrides={...(pendingSource.overrides||{})};for(const input of small.querySelectorAll('[data-match-row]')){overrides[input.dataset.matchRow]={...overrides[input.dataset.matchRow],targetId:input.value};}for(const input of small.querySelectorAll('[data-correct-vin]'))overrides[input.dataset.correctVin]={...overrides[input.dataset.correctVin],vin:input.value};el.disabled=true;try{pendingSource=await previewUpload({uploadId:pendingSource.id,overrides});await refresh();sourceReviewModal();}finally{el.disabled=false;}}
 if(el.dataset.sort){if(sortKey===el.dataset.sort)sortDirection=sortDirection==='asc'?'desc':'asc';else{sortKey=el.dataset.sort;sortDirection='asc';}index=0;render();}
 if(el.dataset.duplicates)duplicatesModal(el.dataset.duplicates);
 if(el.dataset.duplicateField){nav('inventory');duplicateField=el.dataset.duplicateField;duplicateValue=el.dataset.duplicateValue;small.close();render();}
 if(el.dataset.clearDuplicates){duplicateField='';duplicateValue='';index=0;render();}
 if(el.dataset.withoutDriver){nav('inventory');driverFilter='unassigned';render();}
 if(el.dataset.section)sectionModal(el.dataset.section);
 if(el.dataset.driver)driverModal(el.dataset.driver);
 if(el.dataset.resolve)resolveModal(el.dataset.resolve);
 if(el.dataset.merge)mergeModal(el.dataset.merge);
 if(el.dataset.addEvidence)showSmall('Add source evidence',`<form id="evidence-form" class="stack"><label>Source name<input name="sourceName" required></label><label>Page / row / document reference<input name="locator"></label><label>Evidence note<textarea name="note" required minlength="3" rows="4"></textarea></label><div class="error" role="alert"></div><button class="primary">Save evidence</button></form>`);
 if(el.id==='add-btn')openVehicle(null);if(el.id==='import-btn')nav('sources');
 if(el.id==='commit-import'){el.disabled=true;try{const r=await api('/api/import/commit','POST',importData);small.close();await refresh();toast(`${r.added} vehicles added; ${r.matched} existing records received evidence.`);}finally{el.disabled=false;}}
 }catch(e){toast(e.message);}});
let searchTimer;
function scheduleSearchRender(field){
 clearTimeout(searchTimer);const currentPage=page;
 searchTimer=setTimeout(()=>{
  if(page!==currentPage||$('#'+field.id)!==field)return;
  const focused=document.activeElement===field,start=field.selectionStart,end=field.selectionEnd,direction=field.selectionDirection,scroll=field.scrollLeft;
  render();const next=$('#'+field.id);
  if(focused&&next){next.focus({preventScroll:true});try{next.setSelectionRange(start,end,direction);}catch{}next.scrollLeft=scroll;}
 },180);
}
function updateSearchField(field,composing=false){
 if(field.id==='driver-search')driverSearch=field.value;
 else if(field.id==='search'){search=field.value;index=0;}
 else return;
 clearTimeout(searchTimer);if(!composing)scheduleSearchRender(field);
}
document.addEventListener('compositionstart',e=>{if(['search','driver-search'].includes(e.target.id))clearTimeout(searchTimer);});
document.addEventListener('compositionend',e=>updateSearchField(e.target));
document.addEventListener('input',e=>{updateSearchField(e.target,e.isComposing);if(e.target.dataset.correctVin){$('#approve-upload').disabled=true;}});
document.addEventListener('change',e=>{if(e.target.dataset.reviewSelect){if(e.target.checked)selectedReviews.add(e.target.dataset.reviewSelect);else selectedReviews.delete(e.target.dataset.reviewSelect);render();return;}if(e.target.id==='review-page-select'){for(const item of reviewItems().slice(index*25,index*25+25)){if(e.target.checked)selectedReviews.add(item.id);else selectedReviews.delete(item.id);}render();return;}if(e.target.closest('#source-review-form'))updateDecisionSummary();if(e.target.id==='upload-source'){const c=data.sourceTypes[e.target.value];$('#upload-file-label').innerHTML=esc(c.label)+'<input name="file" type="file" accept="'+c.accept+'" required>'; }if(e.target.dataset.matchRow){$('#approve-upload').disabled=true;}if(e.target.id==='driver-check-filter'){driverArea='';driverCheckFilter=e.target.value;render();}if(e.target.id==='section-filter'){sectionFilter=e.target.value;index=0;render();}if(e.target.id==='ownership-filter'){ownershipFilter=e.target.value;index=0;render();}if(e.target.id==='driver-filter'){driverFilter=e.target.value;index=0;render();}if(e.target.id==='filter'){filter=e.target.value;index=0;render();}if(e.target.id==='state-filter'){stateFilter=e.target.value;index=0;render();}if(e.target.closest('#import-form')){importData=null;$('#import-preview').innerHTML='';}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f)),button=f.querySelector('button[type="submit"],button.primary');if(button)button.disabled=true;const err=f.querySelector('.error');if(err)err.textContent='';try{
 if(f.id==='confirm-asset-form'){await api('/api/vehicles/'+f.dataset.id+'/confirm-asset','POST',{version:Number(f.dataset.version)});small.close();await refresh();if(drawer.open)openVehicle(selected,tab);toast('Accounting match confirmed. Asset and lease sources may overlap.');}
 if(f.id==='crash-cancel-form'){await api('/api/vehicles/'+f.dataset.id+'/crashes','POST',{...b,action:'cancel',version:Number(f.dataset.version)});small.close();await refresh();openVehicle(f.dataset.id,'crashes');toast('Incorrect crash canceled. Yellow repair flag removed.');}
 if(f.id==='crash-form'){await api('/api/vehicles/'+f.dataset.id+'/crashes','POST',{...b,version:Number(f.dataset.version)});small.close();await refresh();openVehicle(f.dataset.id,'crashes');toast(b.action==='complete'?'Repair completed. Crash history retained.':'Crash repair saved. Vehicle highlighted yellow.');}
 if(f.id==='bulk-review-form'){const result=await api('/api/issues/confirm','POST',{ids:bulkReviewIds,note:b.note});selectedReviews.clear();small.close();await refresh();toast(`${result.confirmed} review items confirmed.`);}
 if(f.id==='driver-archive-form'){await api('/api/drivers/'+f.dataset.id+'/archive','POST',{...b,version:Number(f.dataset.version),archived:f.dataset.archived==='true'});small.close();await refresh();toast(f.dataset.archived==='true'?'Driver archived.':'Driver restored.');}
 if(f.id==='alias-form'){await api('/api/drivers/'+f.dataset.id+'/aliases','POST',{version:Number(f.dataset.version),aliases:b.aliases.split(/\r?\n/).map(x=>x.trim()).filter(Boolean)});small.close();await refresh();toast('Aliases saved. Insurance comparison updated.');}
 if(f.id==='disposal-form'){const old=getV(f.dataset.id),action=b.operationalState==='Disposed'?'Disposed':'Restored';await api('/api/vehicles/'+old.id,'PUT',{version:Number(f.dataset.version),operationalState:b.operationalState,notes:(old.notes?old.notes+'\n':'')+action+' '+new Date().toISOString().slice(0,10)+': '+b.note.trim(),note:action+': '+b.note.trim()});small.close();index=0;await refresh();toast(action==='Disposed'?'Vehicle moved to Disposed vehicles.':'Vehicle restored to the current register.');}
 if(f.id==='new-driver-form'){await api('/api/driver-register','POST',{...b,vehicleVersion:b.vehicleId?getV(b.vehicleId)?.version:undefined});small.close();await refresh();toast('Driver added.');}
 if(f.id==='source-upload-form'){const file=f.querySelector('[name=file]').files[0];$('#upload-progress').textContent='Reading the report and checking existing records…';const base64=await fileBase64(file);pendingSource=await previewUpload({sourceId:b.sourceId,filename:file.name,base64});await refresh();sourceReviewModal();}
 if(f.id==='source-review-form'){const decisions=Object.fromEntries(Object.entries(b).filter(([k])=>k!=='confirmed'));const r=await api('/api/source-upload/commit','POST',{uploadId:pendingSource.id,decisions,confirmed:b.confirmed==='on'});small.close();await refresh();toast(`Source saved: ${r.driversAdded} drivers added, ${r.vehiclesAdded} vehicles added, ${r.changed} approved updates, ${r.ignored||0} ignored discrepancies, ${r.autoLinked||0} automatic driver links.`);}
 if(f.id==='section-form'){await api('/api/vehicles/'+f.dataset.id+'/section','POST',{section:b.section,version:Number(f.dataset.version)});small.close();await refresh();if(drawer.open)openVehicle(selected,tab);toast('CCS section saved.');}
 if(f.id==='driver-form'){await api('/api/vehicles/'+f.dataset.id+'/driver','POST',{driverId:b.driverId,version:Number(f.dataset.version),...assignmentData(f.dataset.id,b.driverId)});small.close();await refresh();if(drawer.open)openVehicle(selected,tab);toast('Driver assignment saved.');}
 if(f.id==='edit-driver-form'){const d=data.drivers.find(d=>d.id===f.dataset.id),old=data.vehicles.find(v=>v.driverId===f.dataset.id);const changed=b.vehicleId!==undefined&&(b.vehicleId||'')!==(old?.id||'');const payload={...b,version:Number(f.dataset.version)};if(changed){Object.assign(payload,assignmentData(b.vehicleId,f.dataset.id),{vehicleVersion:b.vehicleId?getV(b.vehicleId).version:undefined});}else delete payload.vehicleId;await api('/api/drivers/'+f.dataset.id,'PUT',payload);small.close();await refresh();toast('Driver details and assignment saved.');}

 if(f.id==='vehicle-form'){const old=selected?getV(selected):null;await api(selected?'/api/vehicles/'+selected:'/api/vehicles',selected?'PUT':'POST',{...b,...(old?{version:old.version}:{}),...(old&&b.assignmentDriverId!=='__keep__'&&b.assignmentDriverId!==(old.driverId||'')?assignmentData(old.id,b.assignmentDriverId):{assignmentDriverId:undefined})});drawer.close();await refresh();toast('Vehicle saved.');}
 if(f.id==='verify-form'){await api('/api/vehicles/'+selected+'/verify','POST',{version:getV(selected).version,reviewer:b.reviewer,note:b.note,checks:Object.fromEntries(Object.keys(checks).map(k=>[k,b[k]==='on']))});await refresh();openVehicle(selected,'verify');toast('Verification progress saved.');}
 if(f.id==='resolve-form'){await api('/api/issues/'+f.dataset.id,'PUT',{status:'Resolved',note:b.note});small.close();await refresh();if(drawer.open)openVehicle(selected,tab);toast('Review item resolved.');}
 if(f.id==='merge-form'){const target=getV(b.targetId);await api('/api/vehicles/'+f.dataset.id+'/merge','POST',{...b,version:getV(f.dataset.id).version,targetVersion:target.version});small.close();await refresh();openVehicle(target.id,'evidence');toast('Records reconciled. Evidence and history retained.');}
 if(f.id==='evidence-form'){await api('/api/evidence','POST',{...b,vehicleId:selected});small.close();await refresh();openVehicle(selected,'evidence');toast('Evidence added.');}
 if(f.id==='document-form'){const file=f.querySelector('[name=file]').files[0];if(file.size>5*1024*1024)throw Error('Choose a file no larger than 5 MB.');const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});await api('/api/documents','POST',{vehicleId:b.vehicleId,filename:file.name,category:b.category,base64});await refresh();toast('Document uploaded.');}
 if(f.id==='import-form'){const file=f.querySelector('[name=file]').files[0];if(file.size>3*1024*1024)throw Error('CSV must be under 3 MB.');const csv=await file.text();const r=await api('/api/import/preview','POST',{csv});importData={csv,sourceName:b.sourceName,hash:r.hash};const errors=r.rows.filter(x=>x.error);$('#import-preview').innerHTML=`<h3 class="top-space">Preview: ${r.rows.length} rows</h3><p>${r.rows.filter(x=>x.action==='Create vehicle').length} new vehicles · ${r.rows.filter(x=>x.action==='Add evidence').length} existing matches · ${errors.length} errors</p><div class="table-wrap"><table><thead><tr><th>Row</th><th>VIN</th><th>Result</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${x.row}</td><td class="mono">${esc(x.vin)}</td><td>${esc(x.error||x.action)}</td></tr>`).join('')}</tbody></table></div><div class="form-footer"><button id="commit-import" class="primary" ${errors.length||!r.rows.length?'disabled':''}>Confirm import</button></div>`;}
 }catch(error){if(err)err.textContent=error.message;else toast(error.message);if(f.id==='source-upload-form'&&$('#upload-progress'))$('#upload-progress').textContent='';}finally{if(button)button.disabled=false;}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(navs.some(n=>n[0]===p)&&p!==page){page=p;index=0;render();}});
if(navs.some(n=>n[0]===location.hash.slice(1)))page=location.hash.slice(1);
refresh().catch(e=>content.innerHTML=`<div class="notice amber">Could not load the database: ${esc(e.message)}. Make sure the Node.js server is running, then refresh.</div>`);

